const num=(n,d=0)=>Number.isFinite(Number(n))?Number(n):d, round=n=>Math.round(n*10)/10, uid=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(36).slice(2)}`;
