let selectedDate=dayKey(),lastToday=dayKey(),tab='home',selectedWorkout=S.active?.workout||nextWorkout(),mealTab='All',toastTimeout,exerciseOpen=null;let shortOn=false,shortDrop=[],toastUndo=null,rv=null,swapReason='Machine busy',recentCache=[],gapCache=null,actx=null,openLists=new Set();
const icons={moon:'<path d="M20 14.5A8 8 0 0 1 9.5 4a8 8 0 1 0 10.5 10.5z"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',train:'<path d="M6 5v14M3 8v8m15-11v14m3-11v8M6 12h12"/>',food:'<path d="M5 3v7m3-7v7m-6-7v7q0 3 3 3v8m0-8q3 0 3-3m10-7c-4 4-4 10 0 10h2V3h-2Zm2 10v8"/>',chart:'<path d="M3 3v18h18M6 15l5-5 4 2 6-8"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',play:'<path d="m8 4 12 8-12 8Z" fill="currentColor" stroke="none"/>',arrow:'<path d="m9 5 7 7-7 7"/>',shield:'<path d="m12 2 8 4v7c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="#142338"/><circle cx="16" cy="12" r="2" fill="#142338"/><circle cx="10" cy="18" r="2" fill="#142338"/>',water:'<path d="M12 2S5 10 5 15a7 7 0 0 0 14 0C19 10 12 2 12 2Z"/>',book:'<path d="M12 5C8 2 3 3 3 3v17s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2Zm0 0v17"/>',check:'<path d="m4 12 5 5L20 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',cloud:'<path d="M7 19a5 5 0 1 1 0-10 6 6 0 0 1 12-1 5.5 5.5 0 0 1 0 11H7Z"/>',calendar:'<rect x="3.5" y="5" width="17" height="15.5" rx="3"/><path d="M8 3v4M16 3v4M3.5 10h17"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.more}</svg>`;}
function toast(t,undo=null){const el=$('toast'),host=$('sheet').open?$('sheet'):document.body;if(el.parentNode!==host)host.append(el);toastUndo=undo;el.textContent=t;el.classList.toggle('has-undo',!!undo);if(undo){const b=document.createElement('button');b.type='button';b.dataset.action='toast-undo';b.textContent='Undo';el.append(b);}el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),undo?6500:3500);}
function save(){if(corrupt){warnStorage();return false;}try{S.revision=(S.revision||0)+1;localStorage.setItem(KEY,JSON.stringify(S));storageOK=true;warnStorage();return true;}catch{storageOK=false;warnStorage();return false;}}
function warnStorage(){const el=$('storage-warning');el.hidden=storageOK;el.textContent=corrupt?'Saved data could not be read. The original has not been overwritten. Export a backup from More, then restore a valid backup.':'Browser storage is unavailable or full. Changes are only in this session. Export your backup before closing.';}
