function getWeight(){return [...S.weights].sort((a,b)=>b.date.localeCompare(a.date))[0]?.kg||S.legacyWeight||S.profile.startWeight;}
function totals(date=selectedDate){return S.meals.filter(m=>m.date===date).reduce((a,m)=>({k:a.k+m.k,p:a.p+m.p,c:a.c+m.c,f:a.f+m.f}),{k:0,p:0,c:0,f:0});}
