function currentWeek(){return Math.max(1,Math.floor((dayDate(dayKey())-dayDate(S.profile.startDate))/604800000)+1);}
function weekStart(){const d=dayDate(dayKey());d.setDate(d.getDate()-((d.getDay()+6)%7));return dayKey(d);}
function weekSessions(){return S.sessions.filter(x=>x.date>=weekStart()&&x.date<=dayKey()&&x.status==='complete');}
function cardioMinutes(){return S.cardio.filter(x=>x.date>=weekStart()&&x.date<=dayKey()).reduce((a,x)=>a+x.minutes,0);}
function photo(e,frame=0){return e.illustration?e.image:D.imageBase+e.image+'/'+frame+'.jpg';}
function dose(id,p=S.profile.phase,easy=false,o=null){const e=D.exercises[id];let sets=o?.sets??(e.fixed||(e.core?2:(D.phases[p].sets-(p===3&&!e.main?1:0))));if(easy&&!e.fixed)sets=Math.max(1,sets-1);return {sets,min:o?.min??e.min,max:o?.max??e.max,rest:o?.rest??e.rest,unit:o?.unit??e.unit};}
function doseText(d){return `${d.sets} × ${d.min}–${d.max} ${esc(d.unit)}`;}
