function heading(t,sub=''){return `<div class="sheet-heading"><h2 id="sheet-title">${t}</h2>${sub?`<p class="sub">${sub}</p>`:''}</div>`;}
function friendly(k){const t=dayKey();if(k===t)return 'Today';if(k===shiftDay(t,-1))return 'Yesterday';const d=dayDate(k),y=d.getFullYear()!==dayDate(t).getFullYear()?` ${d.getFullYear()}`:'';return `${DAYS[d.getDay()].slice(0,3)} ${d.getDate()} ${MONTHS[d.getMonth()].slice(0,3)}${y}`;}
function datePicker(){const f=friendly(selectedDate);return `<div class="date-control"><button data-action="date-prev" aria-label="Previous day">‹</button><div class="date-pill">${icon('calendar')}<span aria-hidden="true">${esc(f)}</span><input aria-label="Log date: ${esc(f)}" id="log-date" type="date" value="${selectedDate}" max="${dayKey()}"></div><button data-action="date-next" aria-label="Next day" ${selectedDate===dayKey()?'disabled':''}>›</button></div>`;}
function nav(){const pages=[['home','home','Today'],['train','train','Train'],['food','food','Nutrition'],['progress','chart','Progress']];const html=pages.map(([p,i,t])=>`<button class="nav-item ${tab===p?'active':''}" data-page="${p}" ${tab===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('');$('bottom-nav').innerHTML=html;$('side-nav').innerHTML=html;}
