function chartDomain(vals){const mn=Math.min(...vals),mx=Math.max(...vals),pad=Math.max(0.5,(mx-mn)*0.15);return [mn-pad,mx+pad];}
function trendCard(w,left){const pts=[...S.weights].sort((a,b)=>a.date.localeCompare(b.date)).slice(-12),goal=S.profile.goal,lifts=weekSessions().filter(x=>x.workout!=='SUN').length;let chart='';if(pts.length>=2){const [lo,hi]=chartDomain(pts.map(p=>p.kg)),inGoal=goal>=lo&&goal<=hi,W=300,H=110,x=i=>12+i*(W-24)/(pts.length-1),y=v=>H-8-(v-lo)/(hi-lo)*(H-16),line=pts.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)} ${y(p.kg).toFixed(1)}`).join(' ');chart=`<svg class="trend" viewBox="0 0 ${W} ${H}" aria-hidden="true">${inGoal?`<line x1="0" x2="${W}" y1="${y(goal).toFixed(1)}" y2="${y(goal).toFixed(1)}" class="goal-line"/>`:''}<path d="${line} L${x(pts.length-1).toFixed(1)} ${H} L${x(0).toFixed(1)} ${H} Z" class="trend-fill"/><path d="${line}" class="trend-line"/><circle cx="${x(pts.length-1).toFixed(1)}" cy="${y(pts[pts.length-1].kg).toFixed(1)}" r="5" class="trend-dot"/></svg><span class="trend-goal">${inGoal?'<i class="goal-key"></i>':''}Goal ${goal} kg</span>`;}else chart=`<p class="trend-empty">Weigh in 3 mornings a week to see your line climb toward ${goal} kg.</p>`;
return `<button class="trend-card" data-page="progress"><div class="trend-head"><div><small>Body weight</small><b>${Math.round(w*10)/10}<span> kg</span></b></div><div class="trend-side"><small>To go</small><b>${Math.round(left*10)/10}<span> kg</span></b></div><div class="trend-side"><small>This week</small><b>${lifts}<span>/4</span></b></div></div>${chart}</button>`;}
