function resumeHero(a){const w=D.workouts[a.workout],nm=w?(w.short||String(w.name).split(' · ')[0]):'Workout',{done,total}=sessCounts(a);return `<section class="today ${kindOf(a.workout)} resume"><p class="today-kicker" aria-hidden="true">In progress</p><h2 class="today-word">${esc(nm)}<span class="vh"> in progress</span></h2><div role="progressbar" aria-label="Sets logged" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${done}">${track(done,total,'resume-track')}</div><p class="today-meta">${done} of ${total} sets logged · saved as you log</p><button class="btn today-cta" data-page="train">${icon('play')} Resume</button></section>`;}
