function more(){const menu=[['settings','Settings & targets','Name, calories, protein and start date','settings'],...(E?[['chart','Week in review','Last 7 days, with changes you can apply','review']]:[]),['book','Your 24-week plan','Review each phase before increasing workload','plan'],['shield','Training safety','When to modify, stop or get assessed','safety'],['download','Export backup','Save your entire journal as a JSON file','export'],['upload','Restore backup','Import a previously exported Astra backup','import'],['cloud','Save exercise photos offline','Cache the real photos on this device','offline'],['plus','Install on your iPhone','Add Astra to your Home Screen','install'],['book','Sources & image credits','Where guidance and images come from','sources']];return `<div class="page-title"><div><h1>Account</h1><p class="sub">Astra Coach ${VERSION} · on-device edition</p></div></div><div class="card">${menu.map(([ic,title,sub,action])=>`<button class="menu-row" data-action="${action}">${icon(ic)}<span><strong>${title}</strong><small>${sub}</small></span>${icon('arrow')}</button>`).join('')}</div><div class="callout spaced">${icon('shield')}<span><strong>Local-first, not cloud-backed.</strong><p>Your journal is saved in this browser. It is not uploaded to GitHub or a coaching server. Clearing website data or changing devices can remove access—export a backup regularly. No Apple Health or Garmin sync, background tracking, or automated coaching service is connected.</p></span></div>${Object.keys(S.legacy||{}).length?'<div class="banner spaced">Older app records were found and preserved in your backup. Undated old protein totals and exercise views are not treated as today’s meals or completed workouts.</div>':''}`;}
/* v5.1 · render() rebuilds the scrolling pill rows (workout picker, meal filter) at scrollLeft 0; put the selected pill back in the centre, instantly (no smooth scroll, nothing to do for rows that don't scroll or aren't on the page) */
function centerSelected(){document.querySelectorAll('#main .segmented').forEach(p=>{const b=p.querySelector('.selected');if(!b||p.scrollWidth<=p.clientWidth)return;const pr=p.getBoundingClientRect(),br=b.getBoundingClientRect();p.style.scrollBehavior='auto';p.scrollLeft+=br.left-pr.left-(pr.width-br.width)/2;p.style.scrollBehavior='';});}
function render(){tab=location.hash.slice(1);if(!['home','train','food','progress','more'].includes(tab))tab='home';nav();const h=new Date().getHours();$('greeting').textContent=h<12?'Good morning,':h<18?'Good afternoon,':'Good evening,';$('greeting-name').textContent=`${S.profile.name}. Let's get stronger.`;document.querySelector('.avatar').textContent=S.profile.name.slice(0,2).toUpperCase();$('readiness-button').innerHTML=icon('heart');$('main').innerHTML=({home,train,food,progress,more}[tab])();centerSelected();warnStorage();updateRest();}
