const cf=i=>{for(let j=Math.min(i,rows.length)-1;j>=0;j--)if(rows[j]?.done)return rows[j];},cAttr=(i,k)=>{const r=rows[i]||{},rs=rx?.sets?.[i];if(r.done||r[k]!=null)return '';if(k==='kg'?(isBody||(rx&&rs?.kg!=null)):(k!=='rpe'&&rx&&rx.mode!=='new'&&rs?.reps!=null))return '';return ' data-carried="1"';},kgAt=i=>{const r=rows[i]||{},rs=rx?.sets?.[i],pv=ls[i]||ls[ls.length-1];return r.kg??(rx?(rs?.kg??cf(i)?.kg??(bodyLike?0:'')):(cf(i)?.kg??pv?.kg??0));},repAt=(i,k)=>{const r=rows[i]||{},rs=rx?.sets?.[i],pv=ls[i]||ls[ls.length-1],c=cf(i);return r[k]??(rx&&rx.mode!=='new'?rs?.reps:undefined)??c?.[k]??c?.reps??rs?.reps??pv?.[k]??pv?.reps??p.min;},firstKg=kgAt(Array.from({length:p.sets},(_,i)=>i).find(i=>!rows[i]?.done)??0);
modal(sheetOrder(`${heading(e.name,`${e.kind} · ${e.equipment}`)}<div data-timer></div>${rx?rxCard(id,rx,e,p,active?sl:null):''}<!--g0--><div class="media"><img id="exercise-image" ${e.illustration?'class="illustration"':''} src="${photo(e,0)}" alt="${esc(e.name)} ${e.illustration?'illustration':'position 1'}"></div>${e.illustration?'':`<div class="segmented" aria-label="Exercise photo positions"><button class="selected" data-action="frame" data-id="${id}" data-frame="0">Position 1</button><button data-action="frame" data-id="${id}" data-frame="1">Position 2</button></div>`}<p class="media-credit">${e.illustration?'AI-generated illustration from your approved concept; use the written cues.':'Matched exercise photographs · Free Exercise DB. Photos are references, not a form assessment.'}</p><div class="pills"><span class="pill">${doseText(p)}</span><span class="pill">${icon('clock')} Rest ${p.rest}s</span><span class="pill">${esc(e.muscles)}</span></div><h3>Step by step</h3><ol class="steps">${e.steps.map(x=>`<li>${x}</li>`).join('')}</ol><div class="callout">${icon('shield')}<span><strong>Coach cue</strong><p>${e.cue}</p></span></div><details><summary>Easier option & mistakes to avoid</summary><p><b>Easier:</b> ${e.easier}</p><p><b>Avoid:</b> ${e.avoid}</p></details><!--g1-->${rx?'':`<p class="text-small">${esc(suggestion)}</p>`}${active?`<div class="section-head"><h3>Your sets</h3><small>${isBody?'No external load':esc(e.load)}</small></div><p class="form-tip">Enter what you actually did. Effort 6 = about 4 reps left; 8 = about 2. ${uni?'Log left and right; the lower side is saved as the set.':e.unit.includes('side')?'One set is complete after both sides.':''}</p>${asym?.weak?`<p class="asym">${asym.weak==='left'?'Left':'Right'} ≈${Math.round(num(asym.gapPct))}% behind — start ${asym.weak}, match ${asym.weak==='left'?'right':'left'} to it.</p>`:''}${e.bar?`<p class="plate-line" id="plate-line" data-bar="${e.bar}">${esc(plateText(firstKg,e.bar))}</p>`:''}<div class="set-head ${uni?'uni':''}"><span>Set</span><span>kg</span>${uni?'<span>L</span><span>R</span>':`<span>${e.unit.includes('seconds')?'Sec':'Reps'}</span>`}<span>Effort</span><span>Done</span></div><div id="set-rows">${Array.from({length:p.sets},(_,i)=>{const r=rows[i]||{},pv=ls[i]||ls[ls.length-1],dis=r.done?'disabled':'';return `<div class="set-row ${uni?'uni':''} ${r.done?'logged':''}" data-exercise="${id}" data-index="${i}"><span class="set-n">${i+1}${pv&&!r.done?`<small class="prev">${pv.kg?pv.kg+'×':''}${pv.reps}</small>`:''}</span><input aria-label="Set ${i+1} ${esc(e.load)}" data-column="kg" type="number" inputmode="decimal" min="0" max="300" step="0.5" placeholder="kg" value="${kgAt(i)}"${cAttr(i,'kg')} ${isBody?'readonly':''} ${dis}>${uni?`<input aria-label="Set ${i+1} left side, ${esc(e.unit)}" data-column="repsL" type="number" inputmode="numeric" min="1" max="300" step="1" value="${repAt(i,'repsL')}"${cAttr(i,'repsL')} ${dis}><input aria-label="Set ${i+1} right side, ${esc(e.unit)}" data-column="repsR" type="number" inputmode="numeric" min="1" max="300" step="1" value="${repAt(i,'repsR')}"${cAttr(i,'repsR')} ${dis}>`:`<input aria-label="Set ${i+1} ${esc(e.unit)}" data-column="reps" type="number" inputmode="numeric" min="1" max="300" step="1" value="${repAt(i,'reps')}"${cAttr(i,'reps')} ${dis}>`}<input aria-label="Set ${i+1} effort out of 10" data-column="rpe" type="number" inputmode="decimal" min="1" max="10" step="0.5" placeholder="6" value="${r.rpe??cf(i)?.rpe??''}"${cAttr(i,'rpe')} ${dis}><button data-action="log-set" data-id="${id}" data-index="${i}" aria-label="${r.done?'Undo':'Save'} set ${i+1}">${r.done?'✓':'+'}</button></div>`;}).join('')}</div><div class="hurt-row" role="group" aria-label="Did this exercise hurt?"><small>This hurt?</small>${[['back','Back'],['shoulder','Shoulder'],['other','Other']].map(([k,t])=>`<button class="chip ${flag===k?'on':''}" data-action="hurt" data-id="${id}" data-zone="${k}" aria-pressed="${flag===k}">${t}</button>`).join('')}</div><div class="actions ex-actions">${btn(a.skipped.includes(sl)?'Unskip':'Skip','skip-exercise','secondary',`data-id="${id}" data-slot="${sl}"`)}${e.swaps?.length||sl!==id?btn('Swap','swap','secondary',`data-id="${id}" data-slot="${sl}"`):''}${btn('Next exercise ›','next-exercise','primary',`data-id="${id}" data-slot="${sl}"`)}</div>`:S.active?'<p class="form-tip">This exercise is not part of today’s session.</p>':`<div class="actions">${btn('Start workout to log sets','start','primary full')}</div><p class="form-tip">Looking at a guide never marks an exercise complete.</p>`}`,!!active));
